using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
        }

        public void Dispose()
        {
            _controller?.Dispose();
            _context?.Dispose();
        }

        #region GetNotifications Tests

        [Fact]
        public void GetNotifications_NoNotifications_ReturnsSuccessWithEmptyList()
        {
            // Drain any existing notifications from the static queue
            var service = new NotificationService();
            while (service.ReceiveNotification() != null) { }

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var jsonResult = Assert.IsType<JsonResult>(result);
            Assert.NotNull(jsonResult.Value);

            // Use dynamic to access anonymous type properties
            var value = jsonResult.Value;
            var successProp = value.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(value));

            var countProp = value.GetType().GetProperty("count");
            Assert.NotNull(countProp);
            Assert.Equal(0, (int)countProp.GetValue(value));
        }

        [Fact]
        public void GetNotifications_WithNotifications_ReturnsNotificationsFromQueue()
        {
            // Arrange - drain queue first, then add
            var service = new NotificationService();
            while (service.ReceiveNotification() != null) { }
            service.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "Admin");
            service.SendNotification("Course", "101", "Test Course", EntityOperation.UPDATE, "Admin");

            // Act
            var result = _controller.GetNotifications();

            // Assert
            var jsonResult = Assert.IsType<JsonResult>(result);
            var value = jsonResult.Value;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(value));

            var countProp = value.GetType().GetProperty("count");
            Assert.True((int)countProp.GetValue(value) >= 2);
        }

        [Fact]
        public void GetNotifications_LimitsTo10Notifications()
        {
            // Arrange - drain queue first
            var service = new NotificationService();
            while (service.ReceiveNotification() != null) { }

            // Add 15 notifications
            for (int i = 0; i < 15; i++)
            {
                service.SendNotification("Student", i.ToString(), $"Student {i}", EntityOperation.CREATE, "Admin");
            }

            // Act
            var result = _controller.GetNotifications();

            // Assert
            var jsonResult = Assert.IsType<JsonResult>(result);
            var value = jsonResult.Value;
            var countProp = value.GetType().GetProperty("count");
            Assert.Equal(10, (int)countProp.GetValue(value));
        }

        #endregion

        #region MarkAsRead Tests

        [Fact]
        public void MarkAsRead_ValidId_ReturnsSuccess()
        {
            // Act
            var result = _controller.MarkAsRead(1);

            // Assert
            var jsonResult = Assert.IsType<JsonResult>(result);
            var value = jsonResult.Value;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(value));
        }

        [Fact]
        public void MarkAsRead_AnyId_ReturnsSuccessJson()
        {
            // The in-memory implementation is a no-op, but should still return success
            // Act
            var result = _controller.MarkAsRead(999);

            // Assert
            var jsonResult = Assert.IsType<JsonResult>(result);
            var value = jsonResult.Value;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(value));
        }

        #endregion

        #region Index Tests

        [Fact]
        public void Index_ReturnsView()
        {
            // Act
            var result = _controller.Index();

            // Assert
            Assert.IsType<ViewResult>(result);
        }

        #endregion
    }
}

