using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        #region Constructor Tests

        [Fact]
        public void Constructor_SetsPageIndexCorrectly()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var list = new PaginatedList<string>(items, 10, 2, 3);

            // Assert
            Assert.Equal(2, list.PageIndex);
        }

        [Fact]
        public void Constructor_CalculatesTotalPagesCorrectly()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var list = new PaginatedList<string>(items, 10, 1, 3);

            // Assert
            Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
        }

        [Fact]
        public void Constructor_AddsAllItemsToList()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var list = new PaginatedList<string>(items, 10, 1, 3);

            // Assert
            Assert.Equal(3, list.Count);
            Assert.Contains("a", list);
            Assert.Contains("b", list);
            Assert.Contains("c", list);
        }

        [Theory]
        [InlineData(10, 5, 2)]   // 10 items, page size 5 = 2 pages
        [InlineData(11, 5, 3)]   // 11 items, page size 5 = 3 pages (ceiling)
        [InlineData(1, 10, 1)]   // 1 item, page size 10 = 1 page
        [InlineData(0, 10, 0)]   // 0 items, page size 10 = 0 pages
        [InlineData(100, 10, 10)] // 100 items, page size 10 = 10 pages
        public void Constructor_CalculatesTotalPages_ForVariousCounts(int totalCount, int pageSize, int expectedPages)
        {
            // Arrange
            var items = new List<int>();

            // Act
            var list = new PaginatedList<int>(items, totalCount, 1, pageSize);

            // Assert
            Assert.Equal(expectedPages, list.TotalPages);
        }

        #endregion

        #region HasPreviousPage Tests

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 10, 1, 5);

            // Assert
            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 10, 2, 5);

            // Assert
            Assert.True(list.HasPreviousPage);
        }

        [Theory]
        [InlineData(1, false)]
        [InlineData(2, true)]
        [InlineData(3, true)]
        [InlineData(5, true)]
        public void HasPreviousPage_VariousPages_ReturnsExpected(int pageIndex, bool expected)
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 50, pageIndex, 10);

            // Assert
            Assert.Equal(expected, list.HasPreviousPage);
        }

        #endregion

        #region HasNextPage Tests

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 10, 2, 5); // 2 pages total, on page 2

            // Assert
            Assert.False(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_FirstPageOfMany_ReturnsTrue()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 20, 1, 5); // 4 pages total, on page 1

            // Assert
            Assert.True(list.HasNextPage);
        }

        [Theory]
        [InlineData(1, 10, 5, true)]   // page 1 of 2
        [InlineData(2, 10, 5, false)]  // page 2 of 2 (last)
        [InlineData(1, 5, 5, false)]   // page 1 of 1 (only page)
        [InlineData(3, 20, 5, true)]   // page 3 of 4
        [InlineData(4, 20, 5, false)]  // page 4 of 4 (last)
        public void HasNextPage_VariousScenarios_ReturnsExpected(int pageIndex, int totalCount, int pageSize, bool expected)
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), totalCount, pageIndex, pageSize);

            // Assert
            Assert.Equal(expected, list.HasNextPage);
        }

        #endregion

        #region Create Static Method Tests

        [Fact]
        public void Create_ReturnsCorrectPageOfItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 20).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 2, 5);

            // Assert
            Assert.Equal(5, result.Count);
            Assert.Equal(6, result[0]);  // second page starts at item 6
            Assert.Equal(10, result[4]); // ends at item 10
        }

        [Fact]
        public void Create_FirstPage_ReturnsFirstItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 20).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 5);

            // Assert
            Assert.Equal(5, result.Count);
            Assert.Equal(1, result[0]);
            Assert.Equal(5, result[4]);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(4, result.TotalPages);
        }

        [Fact]
        public void Create_LastPage_MayHaveFewerItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 12).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 3, 5); // page 3 of 3

            // Assert
            Assert.Equal(2, result.Count); // only 2 items on last page (12 - 10)
            Assert.Equal(11, result[0]);
            Assert.Equal(12, result[1]);
        }

        [Fact]
        public void Create_SetsTotalPagesFromSourceCount()
        {
            // Arrange
            var source = Enumerable.Range(1, 23).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Equal(3, result.TotalPages); // ceil(23/10) = 3
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            // Arrange
            var source = Enumerable.Empty<int>().AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }

        #endregion
    }
}

