                LastName = "EnrollTest",
                FirstMidName = "Student",
                EnrollmentDate = DateTime.Now
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            var dept = new Department { Name = "EnrollDept", Budget = 50000, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 8888, Title = "EnrollCourse", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var enrollment = new Enrollment { StudentID = student.ID, CourseID = 8888, Grade = Grade.B };
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            // Act
            var retrieved = _context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .First(e => e.StudentID == student.ID);

            // Assert
            Assert.NotNull(retrieved.Student);
            Assert.Equal("EnrollTest", retrieved.Student.LastName);
            Assert.NotNull(retrieved.Course);
            Assert.Equal("EnrollCourse", retrieved.Course.Title);
            Assert.Equal(Grade.B, retrieved.Grade);
        }

        #endregion
    }
}

