using System;
using System.Linq;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain the static queue to start fresh
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _service?.Dispose();
        }

        #region SendNotification Tests

        [Fact]
        public void SendNotification_WithDisplayName_CreatesNotificationWithCorrectMessage()
        {
            // Act
            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("Student 'John Doe'", notification.Message);
            Assert.Contains("created", notification.Message);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
        {
            // Act
            _service.SendNotification("Course", "101", null, EntityOperation.UPDATE, "Teacher");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("Course (ID: 101)", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_GeneratesCorrectMessage()
        {
            // Act
            _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("Department 'Engineering'", notification.Message);
            Assert.Contains("deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            // Act
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToCurrentTime()
        {
            // Arrange
            var before = DateTime.Now;

            // Act
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "Admin");

            // Assert
            var after = DateTime.Now;
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void SendNotification_OverloadWithoutDisplayName_Works()
        {
            // Act
            _service.SendNotification("Student", "1", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("Student (ID: 1)", notification.Message);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void SendNotification_DifferentOperations_GenerateCorrectMessages(EntityOperation operation, string expectedVerb)
        {
            // Act
            _service.SendNotification("TestEntity", "1", "TestName", operation, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains(expectedVerb, notification.Message);
            Assert.Equal(operation.ToString(), notification.Operation);
        }

        #endregion

        #region ReceiveNotification Tests

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            // Act
            var result = _service.ReceiveNotification();

            // Assert
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleNotifications_ReturnsFIFOOrder()
        {
            // Arrange
            _service.SendNotification("First", "1", "First Item", EntityOperation.CREATE, "Admin");
            _service.SendNotification("Second", "2", "Second Item", EntityOperation.UPDATE, "Admin");
            _service.SendNotification("Third", "3", "Third Item", EntityOperation.DELETE, "Admin");

            // Act & Assert
            var first = _service.ReceiveNotification();
            Assert.Equal("First", first.EntityType);

            var second = _service.ReceiveNotification();
            Assert.Equal("Second", second.EntityType);

            var third = _service.ReceiveNotification();
            Assert.Equal("Third", third.EntityType);

            // Queue should be empty now
            Assert.Null(_service.ReceiveNotification());
        }

        [Fact]
        public void ReceiveNotification_DequeuesNotification_NotAvailableAgain()
        {
            // Arrange
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "Admin");

            // Act
            var first = _service.ReceiveNotification();
            var second = _service.ReceiveNotification();

            // Assert
            Assert.NotNull(first);
            Assert.Null(second);
        }

        #endregion

        #region MarkAsRead Tests

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // Act & Assert (no-op implementation should not throw)
            var exception = Record.Exception(() => _service.MarkAsRead(1));
            Assert.Null(exception);
        }

        [Fact]
        public void MarkAsRead_WithAnyId_DoesNotThrow()
        {
            // Act & Assert
            var exception = Record.Exception(() => _service.MarkAsRead(int.MaxValue));
            Assert.Null(exception);
        }

        #endregion

        #region Dispose Tests

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            // Act & Assert
            var exception = Record.Exception(() => _service.Dispose());
            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_CanBeCalledMultipleTimes()
        {
            // Act & Assert
            var exception = Record.Exception(() =>
            {
                _service.Dispose();
                _service.Dispose();
            });
            Assert.Null(exception);
        }

        #endregion

        #region Queue Capacity Tests

        [Fact]
        public void SendNotification_ExceedsMaxQueueLength_OldestAreRemoved()
        {
            // Arrange - send more than 500 (max queue length)
            for (int i = 0; i < 510; i++)
            {
                _service.SendNotification("Entity", i.ToString(), $"Item {i}", EntityOperation.CREATE, "Admin");
            }

            // Act - receive all remaining
            int count = 0;
            while (_service.ReceiveNotification() != null)
            {
                count++;
            }

            // Assert - should have at most 500 due to trimming
            Assert.True(count <= 500);
        }

        #endregion

        #region Message Generation Tests

        [Fact]
        public void SendNotification_EmptyDisplayName_UsesEntityId()
        {
            // Act
            _service.SendNotification("Student", "42", "", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.Contains("Student (ID: 42)", notification.Message);
        }

        [Fact]
        public void SendNotification_WhitespaceDisplayName_UsesEntityId()
        {
            // Act
            _service.SendNotification("Student", "42", "   ", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.Contains("Student (ID: 42)", notification.Message);
        }

        #endregion
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        #region Constructor Tests

        [Fact]
        public void Constructor_SetsPageIndexCorrectly()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var list = new PaginatedList<string>(items, 10, 2, 3);

            // Assert
            Assert.Equal(2, list.PageIndex);
        }

        [Fact]
        public void Constructor_CalculatesTotalPagesCorrectly()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var list = new PaginatedList<string>(items, 10, 1, 3);

            // Assert
            Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
        }

        [Fact]
        public void Constructor_AddsAllItemsToList()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var list = new PaginatedList<string>(items, 10, 1, 3);

            // Assert
            Assert.Equal(3, list.Count);
            Assert.Contains("a", list);
            Assert.Contains("b", list);
            Assert.Contains("c", list);
        }

        [Theory]
        [InlineData(10, 5, 2)]   // 10 items, page size 5 = 2 pages
        [InlineData(11, 5, 3)]   // 11 items, page size 5 = 3 pages (ceiling)
        [InlineData(1, 10, 1)]   // 1 item, page size 10 = 1 page
        [InlineData(0, 10, 0)]   // 0 items, page size 10 = 0 pages
        [InlineData(100, 10, 10)] // 100 items, page size 10 = 10 pages
        public void Constructor_CalculatesTotalPages_ForVariousCounts(int totalCount, int pageSize, int expectedPages)
        {
            // Arrange
            var items = new List<int>();

            // Act
            var list = new PaginatedList<int>(items, totalCount, 1, pageSize);

            // Assert
            Assert.Equal(expectedPages, list.TotalPages);
        }

        #endregion

        #region HasPreviousPage Tests

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 10, 1, 5);

            // Assert
            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 10, 2, 5);

            // Assert
            Assert.True(list.HasPreviousPage);
        }

        [Theory]
        [InlineData(1, false)]
        [InlineData(2, true)]
        [InlineData(3, true)]
        [InlineData(5, true)]
        public void HasPreviousPage_VariousPages_ReturnsExpected(int pageIndex, bool expected)
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 50, pageIndex, 10);

            // Assert
            Assert.Equal(expected, list.HasPreviousPage);
        }

        #endregion

        #region HasNextPage Tests

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 10, 2, 5); // 2 pages total, on page 2

            // Assert
            Assert.False(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_FirstPageOfMany_ReturnsTrue()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 20, 1, 5); // 4 pages total, on page 1

            // Assert
            Assert.True(list.HasNextPage);
        }

        [Theory]
        [InlineData(1, 10, 5, true)]   // page 1 of 2
        [InlineData(2, 10, 5, false)]  // page 2 of 2 (last)
        [InlineData(1, 5, 5, false)]   // page 1 of 1 (only page)
        [InlineData(3, 20, 5, true)]   // page 3 of 4
        [InlineData(4, 20, 5, false)]  // page 4 of 4 (last)
        public void HasNextPage_VariousScenarios_ReturnsExpected(int pageIndex, int totalCount, int pageSize, bool expected)
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), totalCount, pageIndex, pageSize);

            // Assert
            Assert.Equal(expected, list.HasNextPage);
        }

        #endregion

        #region Create Static Method Tests

        [Fact]
        public void Create_ReturnsCorrectPageOfItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 20).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 2, 5);

            // Assert
            Assert.Equal(5, result.Count);
            Assert.Equal(6, result[0]);  // second page starts at item 6
            Assert.Equal(10, result[4]); // ends at item 10
        }

        [Fact]
        public void Create_FirstPage_ReturnsFirstItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 20).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 5);

            // Assert
            Assert.Equal(5, result.Count);
            Assert.Equal(1, result[0]);
            Assert.Equal(5, result[4]);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(4, result.TotalPages);
        }

        [Fact]
        public void Create_LastPage_MayHaveFewerItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 12).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 3, 5); // page 3 of 3

            // Assert
            Assert.Equal(2, result.Count); // only 2 items on last page (12 - 10)
            Assert.Equal(11, result[0]);
            Assert.Equal(12, result[1]);
        }

        [Fact]
        public void Create_SetsTotalPagesFromSourceCount()
        {
            // Arrange
            var source = Enumerable.Range(1, 23).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Equal(3, result.TotalPages); // ceil(23/10) = 3
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            // Arrange
            var source = Enumerable.Empty<int>().AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }

        #endregion
    }
}

