                HireDate = new DateTime(2020, 1, 1)
            };

            // Act
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.Instructors.FirstOrDefault(i => i.LastName == "InstructorLast");
            Assert.NotNull(retrieved);
            Assert.Equal("InstructorFirst", retrieved.FirstMidName);
            Assert.Equal(new DateTime(2020, 1, 1), retrieved.HireDate);
        }

        [Fact]
        public void Context_CanDeleteStudent()
        {
            // Arrange
            var student = new Student
            {
                LastName = "ToDelete",
                FirstMidName = "Student",
                EnrollmentDate = DateTime.Now
            };
            _context.Students.Add(student);
            _context.SaveChanges();
            var id = student.ID;

            // Act
            _context.Students.Remove(student);
            _context.SaveChanges();

            // Assert
            Assert.Null(_context.Students.Find(id));
        }

        [Fact]
        public void Context_CanUpdateStudent()
        {
            // Arrange
            var student = new Student
            {
                LastName = "Original",
                FirstMidName = "Name",
                EnrollmentDate = DateTime.Now
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            // Act
            student.LastName = "Updated";
            _context.SaveChanges();

            // Assert
            var retrieved = _context.Students.Find(student.ID);
            Assert.Equal("Updated", retrieved.LastName);
        }

        #endregion

        #region Relationship Tests

        [Fact]
        public void Context_CourseAssignment_CompositeKey_Works()
        {
            // Arrange
            var instructor = new Instructor
            {
                LastName = "KeyTest",
                FirstMidName = "Inst",
                HireDate = DateTime.Now
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var dept = new Department { Name = "KeyDept", Budget = 50000, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 7777, Title = "KeyCourse", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            // Act
            var assignment = new CourseAssignment { CourseID = 7777, InstructorID = instructor.ID };
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.CourseAssignments.Find(7777, instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal(7777, retrieved.CourseID);
            Assert.Equal(instructor.ID, retrieved.InstructorID);
        }

        [Fact]
        public void Context_StudentEnrollment_Relationship_Works()
        {
            // Arrange
            var student = new Student
            {
                LastName = "EnrollTest",
                FirstMidName = "Student",
                EnrollmentDate = DateTime.Now
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            var dept = new Department { Name = "EnrollDept", Budget = 50000, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 8888, Title = "EnrollCourse", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var enrollment = new Enrollment { StudentID = student.ID, CourseID = 8888, Grade = Grade.B };
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            // Act
            var retrieved = _context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .First(e => e.StudentID == student.ID);

            // Assert
            Assert.NotNull(retrieved.Student);
            Assert.Equal("EnrollTest", retrieved.Student.LastName);
            Assert.NotNull(retrieved.Course);
            Assert.Equal("EnrollCourse", retrieved.Course.Title);
            Assert.Equal(Grade.B, retrieved.Grade);
        }

        #endregion
    }
}

