using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.CreateWithStudents();
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller?.Dispose();
            _context?.Dispose();
        }

        #region Index Tests

        [Fact]
        public void Index_NoParameters_ReturnsViewWithAllStudents()
        {
            // Act
            var result = _controller.Index(null, null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(5, model.Count);
        }

        [Fact]
        public void Index_WithSearchString_FiltersStudentsByLastName()
        {
            // Act
            var result = _controller.Index(null, null, "Alexander", null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Alexander", model[0].LastName);
        }

        [Fact]
        public void Index_WithSearchString_FiltersStudentsByFirstName()
        {
            // Act
            var result = _controller.Index(null, null, "Carson", null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Carson", model[0].FirstMidName);
        }

        [Fact]
        public void Index_SortByNameDesc_ReturnsStudentsInDescendingOrder()
        {
            // Act
            var result = _controller.Index("name_desc", null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal("Li", model[0].LastName);
        }

        [Fact]
        public void Index_SortByDate_ReturnsStudentsOrderedByEnrollmentDate()
        {
            // Act
            var result = _controller.Index("Date", null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(new DateTime(2020, 9, 1), model[0].EnrollmentDate);
        }

        [Fact]
        public void Index_SortByDateDesc_ReturnsStudentsInDescendingDateOrder()
        {
            // Act
            var result = _controller.Index("date_desc", null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(new DateTime(2022, 9, 1), model[0].EnrollmentDate);
        }

        [Fact]
        public void Index_DefaultSort_ReturnsStudentsOrderedByLastNameAsc()
        {
            // Act
            var result = _controller.Index(null, null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal("Alexander", model[0].LastName);
            Assert.Equal("Alonso", model[1].LastName);
        }

        [Fact]
        public void Index_NewSearchString_ResetsPageToOne()
        {
            // Act
            var result = _controller.Index(null, null, "A", 3) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_NullSearchString_UsesCurrentFilter()
        {
            // Act
            var result = _controller.Index(null, "Li", null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Li", model[0].LastName);
        }

        [Fact]
        public void Index_SetsViewBagCurrentSort()
        {
            // Act
            var result = _controller.Index("name_desc", null, null, null) as ViewResult;

            // Assert
            Assert.Equal("name_desc", _controller.ViewBag.CurrentSort);
        }

        [Fact]
        public void Index_SetsViewBagNameSortParm()
        {
            // When sortOrder is empty, NameSortParm should be "name_desc"
            var result = _controller.Index(null, null, null, null) as ViewResult;
            Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);

            // When sortOrder is "name_desc", NameSortParm should be ""
            result = _controller.Index("name_desc", null, null, null) as ViewResult;
            Assert.Equal("", _controller.ViewBag.NameSortParm);
        }

        [Fact]
        public void Index_SetsViewBagDateSortParm()
        {
            // When sortOrder is not "Date", DateSortParm should be "Date"
            var result = _controller.Index(null, null, null, null) as ViewResult;
            Assert.Equal("Date", _controller.ViewBag.DateSortParm);

            // When sortOrder is "Date", DateSortParm should be "date_desc"
            result = _controller.Index("Date", null, null, null) as ViewResult;
            Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
        }

        #endregion

        #region Details Tests

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Details(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            // Act
            var result = _controller.Details(1) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var student = Assert.IsType<Student>(result.Model);
            Assert.Equal("Alexander", student.LastName);
            Assert.Equal("Carson", student.FirstMidName);
            Assert.Equal(1, student.ID);
        }

        #endregion

        #region Create GET Tests

        [Fact]
        public void Create_Get_ReturnsViewWithStudentDefaultDate()
        {
            // Act
            var result = _controller.Create() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var student = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, student.EnrollmentDate);
        }

        #endregion

        #region Create POST Tests

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            // Arrange
            var student = new Student
            {
                LastName = "NewStudent",
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            // Act
            var result = _controller.Create(student);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_Post_ValidStudent_AddsStudentToDatabase()
        {
            // Arrange
            var student = new Student
            {
                LastName = "NewStudent",
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            // Act
            _controller.Create(student);

            // Assert
            var savedStudent = _context.Students.FirstOrDefault(s => s.LastName == "NewStudent");
            Assert.NotNull(savedStudent);
            Assert.Equal("Test", savedStudent.FirstMidName);
            Assert.Equal(new DateTime(2023, 9, 1), savedStudent.EnrollmentDate);
        }

        [Fact]
        public void Create_Post_MinValueEnrollmentDate_AddsModelError()
        {
            // Arrange
            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "Student",
                EnrollmentDate = DateTime.MinValue
            };

            // Act
            var result = _controller.Create(student) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_Post_DateBeforeValidRange_AddsModelError()
        {
            // Arrange
            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "Student",
                EnrollmentDate = new DateTime(1752, 12, 31)
            };

            // Act
            var result = _controller.Create(student) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            // Arrange
            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "Student",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };
            _controller.ModelState.AddModelError("LastName", "Required");

            // Act
            var result = _controller.Create(student) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(student, result.Model);
        }

        #endregion

        #region Edit GET Tests

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Edit(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Edit(999);

            // Assert
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithStudent()
        {
            // Act
            var result = _controller.Edit(1) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var student = Assert.IsType<Student>(result.Model);
            Assert.Equal("Alexander", student.LastName);
            Assert.Equal(1, student.ID);
        }

        #endregion

        #region Edit POST Tests

        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            // Arrange
            var student = new Student
            {
                ID = 1,
                LastName = "UpdatedName",
                FirstMidName = "Carson",
                EnrollmentDate = new DateTime(2020, 9, 1)
            };
            var existing = _context.Students.Find(1);
            _context.Entry(existing).State = EntityState.Detached;

            // Act
            var result = _controller.Edit(student);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_ValidStudent_UpdatesDatabase()
        {
            // Arrange
            var student = new Student
            {
                ID = 1,
                LastName = "UpdatedName",
                FirstMidName = "UpdatedFirst",
                EnrollmentDate = new DateTime(2020, 9, 1)
            };
            var existing = _context.Students.Find(1);
            _context.Entry(existing).State = EntityState.Detached;

            // Act
            _controller.Edit(student);

            // Assert
            var updated = _context.Students.Find(1);
            Assert.Equal("UpdatedName", updated.LastName);
            Assert.Equal("UpdatedFirst", updated.FirstMidName);
        }

        [Fact]
        public void Edit_Post_MinValueEnrollmentDate_AddsModelError()
        {
            // Arrange
            var student = new Student
            {
                ID = 1,
                LastName = "Test",
                FirstMidName = "Student",
                EnrollmentDate = DateTime.MinValue
            };

            // Act
            var result = _controller.Edit(student) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Edit_Post_InvalidModelState_ReturnsView()
        {
            // Arrange
            var student = new Student
            {
                ID = 1,
                LastName = "Test",
                FirstMidName = "Student",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };
            _controller.ModelState.AddModelError("LastName", "Required");

            // Act
            var result = _controller.Edit(student) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(student, result.Model);
        }

        #endregion

        #region Delete GET Tests

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Delete(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Delete(999);

            // Assert
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithStudent()
        {
            // Act
            var result = _controller.Delete(1) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var student = Assert.IsType<Student>(result.Model);
            Assert.Equal("Alexander", student.LastName);
        }

        #endregion

        #region DeleteConfirmed Tests

        [Fact]
        public void DeleteConfirmed_ValidId_RedirectsToIndex()
        {
            // Act
            var result = _controller.DeleteConfirmed(1);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesStudentFromDatabase()
        {
            // Act
            _controller.DeleteConfirmed(1);

            // Assert
            var student = _context.Students.Find(1);
            Assert.Null(student);
        }

        [Fact]
        public void DeleteConfirmed_ValidId_ReducesStudentCount()
        {
            // Arrange
            var initialCount = _context.Students.Count();

            // Act
            _controller.DeleteConfirmed(1);

            // Assert
            Assert.Equal(initialCount - 1, _context.Students.Count());
        }

        #endregion

