using System;
using System.Linq;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain the static queue to start fresh
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _service?.Dispose();
        }

        #region SendNotification Tests

        [Fact]
        public void SendNotification_WithDisplayName_CreatesNotificationWithCorrectMessage()
        {
            // Act
            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("Student 'John Doe'", notification.Message);
            Assert.Contains("created", notification.Message);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
        {
            // Act
            _service.SendNotification("Course", "101", null, EntityOperation.UPDATE, "Teacher");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("Course (ID: 101)", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_GeneratesCorrectMessage()
        {
            // Act
            _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("Department 'Engineering'", notification.Message);
            Assert.Contains("deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            // Act
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToCurrentTime()
        {
            // Arrange
            var before = DateTime.Now;

            // Act
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "Admin");

            // Assert
            var after = DateTime.Now;
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void SendNotification_OverloadWithoutDisplayName_Works()
        {
            // Act
            _service.SendNotification("Student", "1", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("Student (ID: 1)", notification.Message);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void SendNotification_DifferentOperations_GenerateCorrectMessages(EntityOperation operation, string expectedVerb)
        {
            // Act
            _service.SendNotification("TestEntity", "1", "TestName", operation, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains(expectedVerb, notification.Message);
            Assert.Equal(operation.ToString(), notification.Operation);
        }

        #endregion

        #region ReceiveNotification Tests

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            // Act
            var result = _service.ReceiveNotification();

            // Assert
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleNotifications_ReturnsFIFOOrder()
        {
            // Arrange
            _service.SendNotification("First", "1", "First Item", EntityOperation.CREATE, "Admin");
            _service.SendNotification("Second", "2", "Second Item", EntityOperation.UPDATE, "Admin");
            _service.SendNotification("Third", "3", "Third Item", EntityOperation.DELETE, "Admin");

            // Act & Assert
            var first = _service.ReceiveNotification();
            Assert.Equal("First", first.EntityType);

            var second = _service.ReceiveNotification();
            Assert.Equal("Second", second.EntityType);

            var third = _service.ReceiveNotification();
            Assert.Equal("Third", third.EntityType);

            Assert.Null(_service.ReceiveNotification());
        }

        [Fact]
        public void ReceiveNotification_DequeuesNotification_NotAvailableAgain()
        {
            // Arrange
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "Admin");

            // Act
            var first = _service.ReceiveNotification();
            var second = _service.ReceiveNotification();

            // Assert
            Assert.NotNull(first);
            Assert.Null(second);
        }

        #endregion

        #region MarkAsRead Tests

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // Act & Assert
            var exception = Record.Exception(() => _service.MarkAsRead(1));
            Assert.Null(exception);
        }

        [Fact]
        public void MarkAsRead_WithAnyId_DoesNotThrow()
        {
            // Act & Assert
            var exception = Record.Exception(() => _service.MarkAsRead(int.MaxValue));
            Assert.Null(exception);
        }

        #endregion

        #region Dispose Tests

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            // Act & Assert
            var exception = Record.Exception(() => _service.Dispose());
            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_CanBeCalledMultipleTimes()
        {
            // Act & Assert
            var exception = Record.Exception(() =>
            {
                _service.Dispose();
                _service.Dispose();
            });
            Assert.Null(exception);
        }

        #endregion

        #region Queue Capacity Tests

        [Fact]
        public void SendNotification_ExceedsMaxQueueLength_OldestAreRemoved()
        {
            // Arrange - send more than 500 (max queue length)
            for (int i = 0; i < 510; i++)
            {
                _service.SendNotification("Entity", i.ToString(), $"Item {i}", EntityOperation.CREATE, "Admin");
            }

            // Act - receive all remaining
            int count = 0;
            while (_service.ReceiveNotification() != null)
            {
                count++;
            }

            // Assert - should have at most 500 due to trimming
            Assert.True(count <= 500);
        }

        #endregion

        #region Message Generation Tests

        [Fact]
        public void SendNotification_EmptyDisplayName_UsesEntityId()
        {
            // Act
            _service.SendNotification("Student", "42", "", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.Contains("Student (ID: 42)", notification.Message);
        }

        [Fact]
        public void SendNotification_WhitespaceDisplayName_UsesEntityId()
        {
            // Act
            _service.SendNotification("Student", "42", "   ", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.Contains("Student (ID: 42)", notification.Message);
        }

        #endregion
    }
}

