using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests : IDisposable
    {
        private readonly SchoolContext _context;

        public DbInitializerTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose()
        {
            _context?.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsStudents()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            Assert.Equal(8, _context.Students.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsInstructors()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            Assert.Equal(5, _context.Instructors.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsDepartments()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            Assert.Equal(4, _context.Departments.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourses()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            Assert.Equal(7, _context.Courses.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsEnrollments()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            Assert.Equal(11, _context.Enrollments.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourseAssignments()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            Assert.Equal(8, _context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            Assert.Equal(3, _context.OfficeAssignments.Count());
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            // Arrange - seed first
            DbInitializer.Initialize(_context);
            var studentCount = _context.Students.Count();

            // Act - try to seed again
            DbInitializer.Initialize(_context);

            // Assert - counts should not change
            Assert.Equal(studentCount, _context.Students.Count());
        }

        [Fact]
        public void Initialize_SeedsStudentWithCorrectData()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            var carson = _context.Students.FirstOrDefault(s => s.LastName == "Alexander");
            Assert.NotNull(carson);
            Assert.Equal("Carson", carson.FirstMidName);
            Assert.Equal(DateTime.Parse("2010-09-01"), carson.EnrollmentDate);
        }

        [Fact]
        public void Initialize_SeedsInstructorWithCorrectData()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            var kim = _context.Instructors.FirstOrDefault(i => i.LastName == "Abercrombie");
            Assert.NotNull(kim);
            Assert.Equal("Kim", kim.FirstMidName);
            Assert.Equal(DateTime.Parse("1995-03-11"), kim.HireDate);
        }

        [Fact]
        public void Initialize_DepartmentsHaveAdministrators()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            var english = _context.Departments.FirstOrDefault(d => d.Name == "English");
            Assert.NotNull(english);
            Assert.NotNull(english.InstructorID);
        }

        [Fact]
        public void Initialize_CoursesHaveDepartments()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            var chemistry = _context.Courses.FirstOrDefault(c => c.Title == "Chemistry");
            Assert.NotNull(chemistry);
            Assert.True(chemistry.DepartmentID > 0);
        }

        [Fact]
        public void Initialize_OfficeAssignmentsHaveLocations()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            var offices = _context.OfficeAssignments.ToList();
            Assert.All(offices, o => Assert.False(string.IsNullOrEmpty(o.Location)));
        }

        [Fact]
        public void Initialize_EnrollmentsLinkStudentsAndCourses()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            var enrollments = _context.Enrollments.ToList();
            Assert.All(enrollments, e =>
            {
                Assert.True(e.StudentID > 0);
                Assert.True(e.CourseID > 0);
            });
        }

        [Fact]
        public void Initialize_SomeEnrollmentsHaveGrades()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            var withGrades = _context.Enrollments.Count(e => e.Grade != null);
            var withoutGrades = _context.Enrollments.Count(e => e.Grade == null);
            Assert.True(withGrades > 0);
            Assert.True(withoutGrades > 0);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    /// <summary>
    /// Additional tests for BaseController notification sending and edge cases.
    /// Uses StudentsController as a concrete subclass to test BaseController behavior.
    /// </summary>
    public class BaseControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public BaseControllerTests()
        {
            _context = TestDbContextFactory.CreateWithStudents();
            _controller = new StudentsController(_context);
            // Setup TempData for delete error path
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                new Mock_ITempDataProvider());
        }

        public void Dispose()
        {
            _controller?.Dispose();
            _context?.Dispose();
        }

        [Fact]
        public void Create_Post_ValidStudent_SendsCreateNotification()
        {
            // Arrange - drain the notification queue first
            var notificationService = new Services.NotificationService();
            while (notificationService.ReceiveNotification() != null) { }

            var student = new Student
            {
                LastName = "NotifyTest",
                FirstMidName = "Create",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            // Act
            _controller.Create(student);

            // Assert - verify notification was sent
            var notification = notificationService.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("NotifyTest", notification.Message);
        }

        [Fact]
        public void Edit_Post_ValidStudent_SendsUpdateNotification()
        {
            // Arrange
            var notificationService = new Services.NotificationService();
            while (notificationService.ReceiveNotification() != null) { }

            var student = new Student
            {
                ID = 1,
                LastName = "UpdatedNotify",
                FirstMidName = "Edit",
                EnrollmentDate = new DateTime(2020, 9, 1)
            };
            var existing = _context.Students.Find(1);
            _context.Entry(existing).State = EntityState.Detached;

            // Act
            _controller.Edit(student);

            // Assert
            var notification = notificationService.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Contains("UpdatedNotify", notification.Message);
        }

        [Fact]
        public void DeleteConfirmed_ValidStudent_SendsDeleteNotification()
        {
            // Arrange
            var notificationService = new Services.NotificationService();
            while (notificationService.ReceiveNotification() != null) { }

            // Act
            _controller.DeleteConfirmed(1);

            // Assert
            var notification = notificationService.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("DELETE", notification.Operation);
            Assert.Contains("Alexander", notification.Message);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            // Arrange
            var ctx = TestDbContextFactory.Create();
            var ctrl = new StudentsController(ctx);

            // Act & Assert
            var exception = Record.Exception(() => ctrl.Dispose());
            Assert.Null(exception);
        }
    }

    /// <summary>
    /// Simple ITempDataProvider implementation for test purposes.
    /// </summary>
    internal class Mock_ITempDataProvider : ITempDataProvider
    {
        private IDictionary<string, object> _data = new Dictionary<string, object>();

        public IDictionary<string, object> LoadTempData(HttpContext context)
        {
            return _data;
        }

        public void SaveTempData(HttpContext context, IDictionary<string, object> values)
        {
            _data = values;
        }
    }
}

