+        public void Create_Post_ValidStudent_SendsCreateNotification()
+        {
+            // Arrange - drain the notification queue first
+            var notificationService = new Services.NotificationService();
+            while (notificationService.ReceiveNotification() != null) { }
+
+            var student = new Student
+            {
+                LastName = "NotifyTest",
+                FirstMidName = "Create",
+                EnrollmentDate = new DateTime(2023, 9, 1)
+            };
+
+            // Act
+            _controller.Create(student);
+
+            // Assert - verify notification was sent
+            var notification = notificationService.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Student", notification.EntityType);
+            Assert.Equal("CREATE", notification.Operation);
+            Assert.Contains("NotifyTest", notification.Message);
+        }
+
+        [Fact]
+        public void Edit_Post_ValidStudent_SendsUpdateNotification()
+        {
+            // Arrange
+            var notificationService = new Services.NotificationService();
+            while (notificationService.ReceiveNotification() != null) { }
+
+            var student = new Student
+            {
+                ID = 1,
+                LastName = "UpdatedNotify",
+                FirstMidName = "Edit",
+                EnrollmentDate = new DateTime(2020, 9, 1)
+            };
+            var existing = _context.Students.Find(1);
+            _context.Entry(existing).State = EntityState.Detached;
+
+            // Act
+            _controller.Edit(student);
+
+            // Assert
+            var notification = notificationService.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Student", notification.EntityType);
+            Assert.Equal("UPDATE", notification.Operation);
+            Assert.Contains("UpdatedNotify", notification.Message);
+        }
+
+        [Fact]
+        public void DeleteConfirmed_ValidStudent_SendsDeleteNotification()
+        {
+            // Arrange
+            var notificationService = new Services.NotificationService();
+            while (notificationService.ReceiveNotification() != null) { }
+
+            // Act
+            _controller.DeleteConfirmed(1);
+
+            // Assert
+            var notification = notificationService.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Student", notification.EntityType);
+            Assert.Equal("DELETE", notification.Operation);
+            Assert.Contains("Alexander", notification.Message);
+        }
+
+        [Fact]
+        public void Dispose_DoesNotThrow()
+        {
+            // Arrange
+            var ctx = TestDbContextFactory.Create();
+            var ctrl = new StudentsController(ctx);
+
+            // Act & Assert
+            var exception = Record.Exception(() => ctrl.Dispose());
+            Assert.Null(exception);
+        }
+    }
+
