using System;
using System.IO;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    /// <summary>
    /// Additional tests for file upload success paths and error handling in CoursesController.
    /// </summary>
    public class CoursesControllerFileUploadTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly string _testDir;

        public CoursesControllerFileUploadTests()
        {
            _context = TestDbContextFactory.CreateWithCourses();
            _testDir = Path.Combine(Path.GetTempPath(), $"contoso_test_{Guid.NewGuid()}");
            Directory.CreateDirectory(_testDir);

            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockEnv.Setup(e => e.WebRootPath).Returns(_testDir);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_testDir);
            _mockLogger = new Mock<ILogger<CoursesController>>();
            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
        }

        public void Dispose()
        {
            _controller?.Dispose();
            _context?.Dispose();
            try { Directory.Delete(_testDir, recursive: true); } catch { }
        }

        [Fact]
        public void Create_Post_ValidImage_UploadSucceeds_RedirectsToIndex()
        {
            // Arrange
            var course = new Course { CourseID = 6666, Title = "Upload Test", Credits = 3, DepartmentID = 1 };
            var mockFile = CreateMockFormFile("valid.jpg", 1024);

            // Act
            var result = _controller.Create(course, mockFile.Object);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);

            // Verify the course was saved with image path
            var saved = _context.Courses.Find(6666);
            Assert.NotNull(saved);
            Assert.StartsWith("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
        }

        [Fact]
        public void Create_Post_ValidImage_CreatesFileOnDisk()
        {
            // Arrange
            var course = new Course { CourseID = 6667, Title = "FileTest", Credits = 3, DepartmentID = 1 };
            var mockFile = CreateMockFormFile("test.png", 2048);

            // Act
            _controller.Create(course, mockFile.Object);

            // Assert
            var uploadsDir = Path.Combine(_testDir, "Uploads", "TeachingMaterials");
            Assert.True(Directory.Exists(uploadsDir));
            var files = Directory.GetFiles(uploadsDir);
            Assert.True(files.Length > 0);
        }

        [Fact]
        public void Edit_Post_ValidImage_UploadSucceeds_RedirectsToIndex()
        {
            // Arrange
            var course = new Course { CourseID = 1050, Title = "Updated Chemistry", Credits = 3, DepartmentID = 1 };
            var existing = _context.Courses.Find(1050);
            _context.Entry(existing).State = EntityState.Detached;

            var mockFile = CreateMockFormFile("newimage.jpeg", 1024);

            // Act
            var result = _controller.Edit(course, mockFile.Object);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_ValidImage_WithExistingImage_UpdatesPath()
        {
